scripts.cgroupsEnd:
wsp_end() {
  C=$1; at="/sys/fs/cgroup$1"
  [ -d "$at" ] || return 0
  mine() { g=$(sed -n 's/^0:://p' /proc/$1/cgroup 2>/dev/null); case "$g" in "$C"|"$C"/*) ;; *) return 1 ;; esac; s=$(sed 's/.*) //' /proc/$1/stat 2>/dev/null); [ -n "$s" ] && [ "${s%% *}" != Z ]; }
  left() { L=; for p in $P; do mine "$p" && L="$L $p"; done; P=$L; }
  P=$(find "$at" -name cgroup.procs -exec cat {} + 2>/dev/null)
  [ -n "$P" ] && kill -TERM $P 2>/dev/null
  i=0; left; while [ $i -lt 30 ] && [ -n "$P" ]; do sleep 0.1; i=$((i+1)); left; done
  [ -n "$P" ] && kill -KILL $P 2>/dev/null
  i=0; left; while [ $i -lt 10 ] && [ -n "$P" ]; do sleep 0.1; i=$((i+1)); left; done
  [ -z "$P" ] || { echo "processes$P of $C did not end" >&2; return 1; }
  [ "$2" = 1 ] || return 0
  echo 1 > "$at/cgroup.kill" 2>/dev/null || { Q=$(find "$at" -name cgroup.procs -exec cat {} + 2>/dev/null); [ -n "$Q" ] && kill -KILL $Q 2>/dev/null; }
  i=0; while [ $i -lt 30 ] && [ -d "$at" ]; do find "$at" -depth -type d -exec rmdir {} + 2>/dev/null; [ -d "$at" ] && sleep 0.1; i=$((i+1)); done
  [ -d "$at" ] && { echo "$C still holds processes" >&2; return 1; }
  return 0
}
[ -d '/sys/fs/cgroup/wsp-threads' ] || exit 0
for d in '/sys/fs/cgroup/wsp-threads'/*/; do [ -d "$d" ] || continue; t=$(basename "$d"); wsp_end '/wsp-threads'/"$t" 1 && echo '/sys/fs/cgroup/wsp-threads'/"$t"; done
rmdir '/sys/fs/cgroup/wsp-threads' 2>/dev/null
exit 0
